"""Once-owned logical surfaces over unchanged physical incidence records.

Private topology ranges select the shared surface provider. Native guards
reject duplicate site/span owners before ordinary sweeps consume any mouths.
"""
from . import curved_junction_nodes as boundary
from .curved_network_ownership_nodes import _all, _compare, _exists, _total

c=boundary.c
KEYS=('Logical Clusters','Cluster Sites','Boundary Links','Cluster Spans')
CHAIN_KEYS=('Chain Links','Chain Steps')
MAX_CLUSTERS=16


def selection(g,table,owner):
    return c._select(g,table,_compare(g,c.named(g,'st_lc_owner','INT'),owner))


def registry(g,inp,original):
    """Mark absorbed incidences only after validating their unique owner."""
    declarations=inp.outputs['Logical Clusters'];sites=inp.outputs['Cluster Sites']
    links=inp.outputs['Boundary Links'];spans=inp.outputs['Cluster Spans']
    junctions=inp.outputs['Junctions'];pairs=inp.outputs['Compounds']
    total=c._count(g,declarations);ns=c._count(g,sites);np=c._count(g,spans)
    within=_compare(g,total,MAX_CLUSTERS,'LESS_EQUAL')*_compare(g,ns,64,'LESS_EQUAL')*_compare(g,np,128,'LESS_EQUAL')
    valid=within
    # Ranges are contiguous private records. They never redefine source IDs.
    checks=_exists(g,('st_lg_id','st_lg_site','st_lg_site_start','st_lg_site_count','st_lg_link_start','st_lg_link_count'))
    checks=checks*_compare(g,c.named(g,'st_lg_id','INT'),0,'GREATER_EQUAL')
    checks=checks*_compare(g,_total(g,1,c.named(g,'st_lg_id','INT')),1)
    checks=checks*g.math('GREATER_THAN',c.named(g,'st_lg_join_radius'),1e-6)
    for prefix,table,lower,upper in (('site',sites,2,16),('link',links,3,64)):
        count=c.named(g,'st_lg_'+prefix+'_count','INT');start=c.named(g,'st_lg_'+prefix+'_start','INT')
        sum_node=g.node('GeometryNodeAccumulateField');sum_node.data_type='INT';sum_node.domain='POINT'
        g.bind(count,sum_node.inputs['Value'])
        checks=checks*_compare(g,start,sum_node.outputs['Trailing'])
        checks=checks*_compare(g,count,lower,'GREATER_EQUAL')*_compare(g,count,upper,'LESS_EQUAL')
        valid=valid*_compare(g,c._stat(g,declarations,count,'Sum'),c._count(g,table))
        at=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);owner=c.named(g,'st_lc_owner','INT')
        start=c._read(g,declarations,'st_lg_'+prefix+'_start',owner,'INT')
        count=c._read(g,declarations,'st_lg_'+prefix+'_count',owner,'INT')
        good=_exists(g,('st_lc_owner',))*_compare(g,owner,0,'GREATER_EQUAL')*_compare(g,owner,total,'LESS_THAN')
        good=good*_compare(g,at,start,'GREATER_EQUAL')*_compare(g,at,start+count,'LESS_THAN')
        valid=valid*_all(g,table,good)
    valid=valid*_all(g,declarations,checks)
    original=c._store(g,original,'st_cn_logical_owner',-1,'INT')
    ri=g.node('GeometryNodeRepeatInput','Assign original physical sites to unique logical owners')
    ro=g.node('GeometryNodeRepeatOutput');ro.repeat_items.new('BOOLEAN','Valid');ri.pair_with_output(ro)
    g.bind(original,ri.inputs['Geometry']);g.bind(valid,ri.inputs['Valid'])
    g.bind(c.choose(g,within,ns,0,'INT'),ri.inputs['Iterations']);at=c.V(g,ri.outputs['Iteration'])
    site=c._read(g,sites,'st_lc_site',at,'INT');owner=c._read(g,sites,'st_lc_owner',at,'INT')
    first=c._read(g,junctions,'st_cj_range_start',site,'INT');count=c._read(g,junctions,'st_cj_range_count',site,'INT')
    index=c.named(g,'st_cj_input_index','INT')
    belongs=_compare(g,index,first,'GREATER_EQUAL')*_compare(g,index,first+count,'LESS_THAN')
    good=_compare(g,site,0,'GREATER_EQUAL')*_compare(g,site,c._count(g,junctions),'LESS_THAN')
    good=good*_compare(g,c._read(g,sites,'st_lc_junction_id',at,'INT'),c._read(g,junctions,'st_cj_junction_id',site,'INT'))
    good=good*_compare(g,count,c._read(g,sites,'st_lc_count',at,'INT'))
    good=good*_compare(g,c._stat(g,ri.outputs['Geometry'],belongs,'Sum'),count)
    fresh=_compare(g,c.named(g,'st_cn_logical_owner','INT'),-1)*(1.-c.named(g,'st_cn_absorbed','BOOLEAN'))
    good=good*_all(g,ri.outputs['Geometry'],c.choose(g,belongs,fresh,1.))
    pair_match=_compare(g,c.named(g,'st_cp_site_a','INT'),site)+_compare(g,c.named(g,'st_cp_site_b','INT'),site)
    good=good*_compare(g,c._stat(g,pairs,pair_match,'Sum'),0)
    owner_value=c.choose(g,belongs,owner,c.named(g,'st_cn_logical_owner','INT'),'INT')
    marked=c._store(g,ri.outputs['Geometry'],'st_cn_logical_owner',owner_value,'INT')
    g.bind(marked,ro.inputs['Geometry']);g.bind(c.V(g,ri.outputs['Valid'])*good,ro.inputs['Valid'])
    # Each absorbed original span must name two opposite, exclusively owned
    # incidences. The common ownership guard checks their semantic identities.
    si=g.node('GeometryNodeRepeatInput','Absorb each original internal span exactly once')
    so=g.node('GeometryNodeRepeatOutput');so.repeat_items.new('BOOLEAN','Valid');si.pair_with_output(so)
    g.bind(ro.outputs['Geometry'],si.inputs['Geometry']);g.bind(ro.outputs['Valid'],si.inputs['Valid'])
    g.bind(c.choose(g,within,np,0,'INT'),si.inputs['Iterations']);at=c.V(g,si.outputs['Iteration'])
    span=c._read(g,spans,'st_lc_span',at,'INT');owner=c._read(g,spans,'st_lc_owner',at,'INT')
    match=_compare(g,c.named(g,'st_cj_span_index','INT'),span)
    good=_compare(g,span,0,'GREATER_EQUAL')*_compare(g,span,c._count(g,inp.outputs['Mapping']),'LESS_THAN')
    good=good*_compare(g,owner,0,'GREATER_EQUAL')*_compare(g,owner,total,'LESS_THAN')
    good=good*_compare(g,c._stat(g,si.outputs['Geometry'],match,'Sum'),2)
    kept=_compare(g,c.named(g,'st_cn_logical_owner','INT'),owner)*(1.-c.named(g,'st_cn_absorbed','BOOLEAN'))
    good=good*_all(g,si.outputs['Geometry'],c.choose(g,match,kept,1.))
    marked=c._store(g,si.outputs['Geometry'],'st_cn_absorbed',g.math('MAXIMUM',c.named(g,'st_cn_absorbed','BOOLEAN'),match),'BOOLEAN')
    g.bind(marked,so.inputs['Geometry']);g.bind(c.V(g,si.outputs['Valid'])*good,so.inputs['Valid'])
    return so.outputs['Geometry'],c.V(g,so.outputs['Valid'])


def append_choice(g,inp,at,original,ordinary_geo,ordinary_mouths,ordinary_status,skip,*,local_frames,internal_connectors=False,shared_logical=False,identities=None,interpolation=False):
    """Replace one cluster's first site with its surface; skip its other sites."""
    from . import curved_compound_surface_nodes
    declarations=inp.outputs['Logical Clusters'];sites=inp.outputs['Cluster Sites']
    match=_compare(g,c.named(g,'st_lc_site','INT'),at)
    member=c._stat(g,sites,match,'Sum')
    owner=c._stat(g,sites,match*c.named(g,'st_lc_owner','INT'),'Sum')
    selected=selection(g,sites,owner)
    # Independently require the declared leader to be the minimum site index;
    # malformed private ranges must not duplicate or omit a surface.
    leader=c._read(g,declarations,'st_lg_site',owner,'INT')
    first=_compare(g,at,leader)*member
    leader_ok=_compare(g,leader,c._stat(g,selected,c.named(g,'st_lc_site','INT'),'Min'))
    call=g.node('GeometryNodeGroup','Shared logical cluster surface')
    call.node_tree=(curved_compound_surface_nodes.framed if local_frames else curved_compound_surface_nodes.build)(
        logical_cluster=True,guard_internal_footprints=internal_connectors,interpolation=interpolation)
    if identities is not None:
        from . import curved_mouth_identity_nodes
        call.node_tree=curved_mouth_identity_nodes.build(call.node_tree)
    for key in ('Sources','Mapping','Junctions','Cell Size','Height Exaggeration','Samples Per Side','Relax Iterations'):
        g.bind(inp.outputs[key],call.inputs[key])
    g.bind(original,call.inputs['Approaches']);g.bind(selected,call.inputs['Cluster Sites'])
    g.bind(selection(g,inp.outputs['Boundary Links'],owner),call.inputs['Boundary Links'])
    g.bind(c._read(g,declarations,'st_lg_join_radius',owner),call.inputs['Join Radius'])
    results={key:call.outputs[key] for key in ('Geometry','Mouths','Status')}
    if identities is not None:results['Mouth Identities']=call.outputs['Mouth Identities']
    if shared_logical:
        from . import curved_chain_surface_nodes
        chain=g.node('GeometryNodeGroup','Original multi-owner boundary program')
        chain.node_tree=(curved_chain_surface_nodes.framed(interpolation=interpolation) if local_frames
                         else curved_chain_surface_nodes.build(strip_center=True,interpolation=interpolation))
        if identities is not None:chain.node_tree=curved_mouth_identity_nodes.build(chain.node_tree)
        chain_sites=selected
        for key in ('site','junction_id','first','count'):
            chain_sites=c._store(g,chain_sites,'st_lq_'+key,c.named(g,'st_lc_'+key,'INT'),'INT')
        for key in ('Sources','Mapping','Junctions','Cell Size','Height Exaggeration','Samples Per Side','Relax Iterations'):
            g.bind(inp.outputs[key],chain.inputs[key])
        g.bind(original,chain.inputs['Approaches']);g.bind(chain_sites,chain.inputs['Chain Sites'])
        for key in CHAIN_KEYS:
            table=c._select(g,inp.outputs[key],_compare(g,c.named(g,'st_lq_cluster','INT'),owner))
            g.bind(table,chain.inputs[key])
        use_chain=c._read(g,declarations,'st_lg_chain',owner,'INT')
        leader_ok=leader_ok*(_compare(g,use_chain,0)+_compare(g,use_chain,1))
        results={key:c.choose(g,use_chain,chain.outputs[key],value,'GEOMETRY') for key,value in results.items()}
    values=[c.choose(g,first,results[key],other,'GEOMETRY') for key,other in
            (('Geometry',ordinary_geo),('Mouths',ordinary_mouths),('Status',ordinary_status))]
    values[2]=c._store(g,values[2],'st_cn_logical',first,'BOOLEAN')
    values[2]=c._store(g,values[2],'st_cn_logical_id',c.choose(g,first,c._read(g,declarations,'st_lg_id',owner,'INT'),-1,'INT'),'INT')
    if interpolation:
        # Both logical constructions now carry the selected source mode.
        # Their own path, frame and footprint guards still determine validity.
        # Capability is explicit because logical status replaces the ordinary
        # status, whose interpolation marker is not present on these records.
        supported=c.choose(g,member,True,c.named(g,'interpolation_supported','BOOLEAN'),'BOOLEAN')
        values[2]=c._store(g,values[2],'interpolation_supported',supported,'BOOLEAN')
        values[2]=c._store(g,values[2],'valid',c.named(g,'valid','BOOLEAN')*c.named(g,'interpolation_supported','BOOLEAN'),'BOOLEAN')
    result=(*values,g.math('MAXIMUM',skip,member*(1.-first)),c.choose(g,member,leader_ok,1.))
    if identities is not None:return (*result,c.choose(g,first,results['Mouth Identities'],identities,'GEOMETRY'))
    return result
